import React, { useState } from 'react';

type Page = 'scan' | 'login' | 'booking' | 'payment' | 'confirmation';

interface BookingData {
  name: string;
  mobile: string;
  checkinDate: string;
  checkoutDate: string;
  paymentAmount: number;
  paymentType: 'advance' | 'full' | 'custom';
  totalAmount: number;
  customAmount: number;
  whatsappNotification: boolean;
  profilePhoto: string | null;
}

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('scan');
  const [bookingData, setBookingData] = useState<BookingData>({
    name: '',
    mobile: '',
    checkinDate: '',
    checkoutDate: '',
    paymentAmount: 1000,
    paymentType: 'advance',
    totalAmount: 3500,
    customAmount: 1000,
    whatsappNotification: true,
    profilePhoto: null
  });

  const renderPage = () => {
    switch (currentPage) {
      case 'scan':
        return <QRScanPage onScanSuccess={() => setCurrentPage('login')} />;
      case 'login':
        return <LoginPage 
          bookingData={bookingData}
          setBookingData={setBookingData}
          onNext={() => setCurrentPage('booking')} 
          onBack={() => setCurrentPage('scan')} 
        />;
      case 'booking':
        return (
          <BookingPage 
            bookingData={bookingData}
            setBookingData={setBookingData}
            onNext={() => setCurrentPage('payment')}
            onBack={() => setCurrentPage('login')}
          />
        );
      case 'payment':
        return (
          <PaymentPage 
            amount={bookingData.paymentAmount}
            onSuccess={() => {
              setCurrentPage('confirmation');
            }}
            onBack={() => setCurrentPage('booking')}
          />
        );
      case 'confirmation':
        return <ConfirmationPage bookingData={bookingData} onNewBooking={() => {
          setCurrentPage('scan');
          setBookingData({ name: '', mobile: '', checkinDate: '', checkoutDate: '', paymentAmount: 1000, paymentType: 'advance', totalAmount: 3500, customAmount: 1000, whatsappNotification: true, profilePhoto: null });
        }} />;
      default:
        return <QRScanPage onScanSuccess={() => setCurrentPage('login')} />;
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'Arial, sans-serif'
    }}>
      {renderPage()}
    </div>
  );
};

// QR Scan Page
const QRScanPage: React.FC<{ onScanSuccess: () => void }> = ({ onScanSuccess }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [countdown, setCountdown] = useState(3);

  React.useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isScanning && countdown > 0) {
      interval = setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (isScanning && countdown === 0) {
      setTimeout(() => {
        onScanSuccess();
        setIsScanning(false);
        setCountdown(3);
      }, 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isScanning, countdown, onScanSuccess]);

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '500px',
        width: '100%',
        textAlign: 'center',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <div style={{ fontSize: '4rem', marginBottom: '20px' }}>

        </div>
        <h1 style={{ color: '#802319ff', marginBottom: '10px', fontSize: '2.5rem', fontWeight: '700' }}>
          Jharkhand Chhatriya Sangh Bhawan
        </h1>
        <p style={{ color: '#666', marginBottom: '30px', fontSize: '1.1rem' }}>
          Scan QR code to start your booking
        </p>

        <div style={{
          border: '3px dashed #667eea',
          borderRadius: '15px',
          padding: '40px',
          marginBottom: '30px',
          minHeight: '200px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          background: isScanning ? '#f0f8ff' : '#fafafa'
        }}>
          {isScanning ? (
            <>
              <div style={{ 
                fontSize: '3rem', 
                marginBottom: '20px',
                animation: 'pulse 1s infinite'
              }}>📷</div>
              <h3 style={{ color: '#667eea', margin: '0 0 10px 0' }}>Scanning QR Code...</h3>
              {countdown > 0 ? (
                <p style={{ color: '#666', margin: 0 }}>Detecting in {countdown}s</p>
              ) : (
                <p style={{ color: '#4CAF50', margin: 0 }}>✅ QR Code Found!</p>
              )}
            </>
          ) : (
            <>
              <div style={{ fontSize: '3rem', marginBottom: '20px', opacity: 0.5 }}>📷</div>
              <h3 style={{ color: '#666', margin: '0 0 10px 0' }}>Camera Ready</h3>
              <p style={{ color: '#999', margin: 0 }}>Click "Start Scanning" to begin</p>
            </>
          )}
        </div>

        {!isScanning ? (
          <button
            onClick={() => setIsScanning(true)}
            style={{
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '25px',
              padding: '15px 40px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'transform 0.2s ease',
              boxShadow: '0 5px 15px rgba(102, 126, 234, 0.3)'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
          >
            Start Scanning
          </button>
        ) : (
          <button
            onClick={() => {
              setIsScanning(false);
              setCountdown(3);
            }}
            style={{
              background: '#ff4757',
              color: 'white',
              border: 'none',
              borderRadius: '25px',
              padding: '15px 40px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer'
            }}
          >
            ⏹ Stop Scanning
          </button>
        )}

        <div style={{ marginTop: '30px', padding: '15px', background: '#e8f4fd', borderRadius: '10px' }}>
          <p style={{ color: '#1e88e5', margin: 0, fontSize: '0.9rem' }}>
            💡 <strong>Demo Mode:</strong> This will simulate QR code scanning for testing
          </p>
        </div>
      </div>
    </div>
  );
};

// Login/Register Page
const LoginPage: React.FC<{ 
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void; 
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validate name
    if (!bookingData.name.trim()) {
      alert('Please enter your full name');
      return;
    }

    // Validate mobile number
    if (!bookingData.mobile.trim()) {
      alert('Please enter your mobile number');
      return;
    }

    if (bookingData.mobile.length !== 10) {
      alert('Mobile number must be exactly 10 digits');
      return;
    }

    if (!/^[0-9]+$/.test(bookingData.mobile)) {
      alert('Mobile number should contain only numbers');
      return;
    }

    onNext();
  };

  // Function to capitalize each word
  const capitalizeWords = (str: string) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };

  // Function to handle name input with auto-capitalization
  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    // Only allow letters and spaces
    const filteredValue = value.replace(/[^a-zA-Z\s]/g, '');
    // Capitalize first letter of each word
    const capitalizedValue = capitalizeWords(filteredValue);
    setBookingData({ ...bookingData, name: capitalizedValue });
  };

  // Function to handle mobile input with digit restriction
  const handleMobileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    // Only allow numbers and limit to 10 digits
    const filteredValue = value.replace(/[^0-9]/g, '').slice(0, 10);
    setBookingData({ ...bookingData, mobile: filteredValue });
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Check file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        alert('Photo size should be less than 5MB');
        return;
      }

      // Check file type
      if (!file.type.startsWith('image/')) {
        alert('Please select a valid image file');
        return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        setBookingData({ ...bookingData, profilePhoto: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const removePhoto = () => {
    setBookingData({ ...bookingData, profilePhoto: null });
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '450px',
        width: '100%',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <button
          onClick={onBack}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            marginBottom: '20px',
            color: '#667eea'
          }}
        >
          ← Back
        </button>

        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ position: 'relative', display: 'inline-block', marginBottom: '15px' }}>
            {bookingData.profilePhoto ? (
              <div style={{ position: 'relative' }}>
                <img 
                  src={bookingData.profilePhoto} 
                  alt="Profile" 
                  style={{
                    width: '80px',
                    height: '80px',
                    borderRadius: '50%',
                    objectFit: 'cover',
                    border: '3px solid #667eea',
                    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                  }}
                />
                <button
                  onClick={removePhoto}
                  style={{
                    position: 'absolute',
                    top: '-5px',
                    right: '-5px',
                    background: '#ff4757',
                    color: 'white',
                    border: 'none',
                    borderRadius: '50%',
                    width: '24px',
                    height: '24px',
                    cursor: 'pointer',
                    fontSize: '12px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}
                >
                  ×
                </button>
              </div>
            ) : (
              <div style={{ fontSize: '3rem', marginBottom: '0' }}>👤</div>
            )}

            <div style={{ marginTop: '10px' }}>
              <label style={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                padding: '8px 16px',
                borderRadius: '20px',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: '500',
                display: 'inline-block',
                transition: 'transform 0.2s ease'
              }}>
                📷 {bookingData.profilePhoto ? 'Change Photo' : 'Add Photo'}
                <input
                  type="file"
                  accept="image/*"
                  onChange={handlePhotoUpload}
                  style={{ display: 'none' }}
                />
              </label>
            </div>
          </div>

          <h2 style={{ color: '#333', margin: '0 0 10px 0', fontSize: '2rem', fontWeight: '300' }}>
            Customer Details
          </h2>
          <p style={{ color: '#666', margin: 0 }}>Enter your information to continue</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              👤 Full Name
            </label>
            <input
              type="text"
              value={bookingData.name}
              onChange={handleNameChange}
              placeholder="Enter your full name"
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                transition: 'border-color 0.3s ease',
                boxSizing: 'border-box'
              }}
              onFocus={(e) => e.target.style.borderColor = '#667eea'}
              onBlur={(e) => e.target.style.borderColor = '#e1e8ed'}
              required
            />
            <div style={{ fontSize: '0.8rem', color: '#666', marginTop: '5px' }}>
              Only letters and spaces allowed. First letter of each word will be capitalized.
            </div>
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📱 Mobile Number
            </label>
            <input
              type="tel"
              value={bookingData.mobile}
              onChange={handleMobileChange}
              placeholder="Enter your 10-digit mobile number"
              maxLength={10}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                transition: 'border-color 0.3s ease',
                boxSizing: 'border-box'
              }}
              onFocus={(e) => e.target.style.borderColor = '#667eea'}
              onBlur={(e) => e.target.style.borderColor = '#e1e8ed'}
              required
            />
            <div style={{ fontSize: '0.8rem', color: '#666', marginTop: '5px' }}>
              {bookingData.mobile.length}/10 digits entered. Only numbers allowed.
            </div>
          </div>

          <div style={{ marginBottom: '30px' }}>
            <label style={{
              display: 'flex',
              alignItems: 'center',
              cursor: 'pointer',
              padding: '15px',
              border: '2px solid #e1e8ed',
              borderRadius: '10px',
              transition: 'border-color 0.3s ease',
              background: bookingData.whatsappNotification ? '#f0f8ff' : 'transparent'
            }}>
              <input
                type="checkbox"
                checked={bookingData.whatsappNotification}
                onChange={(e) => setBookingData({ ...bookingData, whatsappNotification: e.target.checked })}
                style={{
                  marginRight: '12px',
                  transform: 'scale(1.2)'
                }}
              />
              <div>
                <div style={{ fontWeight: '600', color: '#333', marginBottom: '4px' }}>
                  📲 WhatsApp Notifications
                </div>
                <div style={{ fontSize: '0.9rem', color: '#666' }}>
                  Get instant booking confirmation and updates on WhatsApp
                </div>
              </div>
            </label>
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '15px',
              padding: '18px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'transform 0.2s ease',
              boxShadow: '0 5px 15px rgba(102, 126, 234, 0.3)'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
          >
            Continue to Booking →
          </button>
        </form>
      </div>
    </div>
  );
};

// Booking Page
const BookingPage: React.FC<{
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void;
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {

  // Calculate total amount based on dates
  const calculateTotalAmount = (checkinDate: string, checkoutDate: string) => {
    if (!checkinDate || !checkoutDate) return 3500; // Default amount

    const checkin = new Date(checkinDate);
    const checkout = new Date(checkoutDate);
    const diffTime = Math.abs(checkout.getTime() - checkin.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    // Base rate: ₹3500 per day
    const baseRate = 3500;
    const totalAmount = Math.max(diffDays * baseRate, 3500); // Minimum ₹3500

    return totalAmount;
  };

  // Calculate minimum advance payment
  const calculateMinAdvance = (totalAmount: number, days: number) => {
    if (days <= 1) {
      return 1000; // Single day minimum ₹1000
    } else {
      return Math.ceil(totalAmount * 0.3); // 30% for multiple days
    }
  };

  // Update total amount when dates change
  React.useEffect(() => {
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      const checkin = new Date(bookingData.checkinDate);
      const checkout = new Date(bookingData.checkoutDate);
      const days = Math.ceil(Math.abs(checkout.getTime() - checkin.getTime()) / (1000 * 60 * 60 * 24));
      const newTotalAmount = calculateTotalAmount(bookingData.checkinDate, bookingData.checkoutDate);
      const minAdvance = calculateMinAdvance(newTotalAmount, days);

      setBookingData({ 
        ...bookingData, 
        totalAmount: newTotalAmount,
        // Reset payment amount if it exceeds new total or below minimum
        paymentAmount: bookingData.paymentType === 'full' ? newTotalAmount : 
                      bookingData.paymentType === 'advance' ? minAdvance :
                      bookingData.paymentType === 'custom' && (bookingData.paymentAmount > newTotalAmount || bookingData.paymentAmount < minAdvance) ? minAdvance : bookingData.paymentAmount,
        customAmount: Math.max(minAdvance, Math.min(bookingData.customAmount, newTotalAmount))
      });
    }
  }, [bookingData.checkinDate, bookingData.checkoutDate]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      if (new Date(bookingData.checkinDate) >= new Date(bookingData.checkoutDate)) {
        alert('Check-out date must be after check-in date');
        return;
      }
      onNext();
    } else {
      alert('Please select both check-in and check-out dates');
    }
  };

  // Generate available dates (next 120 days to cover through March)
  const getAvailableDates = () => {
    const dates = [];
    const today = new Date();
    for (let i = 0; i < 120; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      dates.push(date.toISOString().split('T')[0]);
    }
    return dates;
  };

  const availableDates = getAvailableDates();

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '500px',
        width: '100%',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <button
          onClick={onBack}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            marginBottom: '20px',
            color: '#667eea'
          }}
        >
          ← Back
        </button>

        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ fontSize: '3rem', marginBottom: '15px' }}>📅</div>
          <h2 style={{ color: '#333', margin: '0 0 10px 0', fontSize: '2rem', fontWeight: '300' }}>
            Booking Details
          </h2>
          <p style={{ color: '#666', margin: 0 }}>Select your check-in and check-out dates</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📅 Check-in Date
            </label>
            <select
              value={bookingData.checkinDate}
              onChange={(e) => {
                const newCheckinDate = e.target.value;
                const newData = { ...bookingData, checkinDate: newCheckinDate };

                // Clear checkout date if it's invalid (same or before new checkin date)
                if (bookingData.checkoutDate && bookingData.checkoutDate <= newCheckinDate) {
                  newData.checkoutDate = '';
                }

                setBookingData(newData);
              }}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                boxSizing: 'border-box',
                background: 'white'
              }}
              required
            >
              <option value="">Select check-in date</option>
              {availableDates.map(date => (
                <option key={date} value={date}>
                  {new Date(date).toLocaleDateString('en-US', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📅 Check-out Date
            </label>
            <select
              value={bookingData.checkoutDate}
              onChange={(e) => setBookingData({ ...bookingData, checkoutDate: e.target.value })}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                boxSizing: 'border-box',
                background: 'white'
              }}
              required
            >
              <option value="">Select check-out date</option>
              {availableDates.map(date => {
                // Disable dates that are same as or before check-in date
                const isDisabled = Boolean(bookingData.checkinDate && date <= bookingData.checkinDate);
                return (
                  <option key={date} value={date} disabled={isDisabled}>
                    {new Date(date).toLocaleDateString('en-US', { 
                      weekday: 'long', 
                      year: 'numeric', 
                      month: 'long', 
                      day: 'numeric' 
                    })}
                  </option>
                );
              })}
            </select>
            {bookingData.checkinDate && (
              <div style={{ fontSize: '0.8rem', color: '#666', marginTop: '5px' }}>
                Only dates after {new Date(bookingData.checkinDate).toLocaleDateString('en-US', { 
                  month: 'short', 
                  day: 'numeric' 
                })} are available for check-out
              </div>
            )}
          </div>

          <div style={{
            background: '#f8f9fa',
            padding: '20px',
            borderRadius: '10px',
            marginBottom: '30px',
            border: '1px solid #e9ecef'
          }}>
            <h3 style={{ margin: '0 0 20px 0', color: '#333', fontSize: '1.2rem' }}>💰 Payment Summary</h3>

            <div style={{ marginBottom: '20px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <span style={{ color: '#666' }}>Total Booking Amount:</span>
                <span style={{ fontWeight: 'bold', color: '#333', fontSize: '1.1rem' }}>₹{bookingData.totalAmount}</span>
              </div>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <label style={{ display: 'block', marginBottom: '10px', color: '#333', fontWeight: '500' }}>
                💳 Payment Option:
              </label>

              <div style={{ marginBottom: '10px' }}>
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', padding: '10px', border: bookingData.paymentType === 'advance' ? '2px solid #667eea' : '2px solid #e1e8ed', borderRadius: '8px', marginBottom: '10px' }}>
                  <input
                    type="radio"
                    name="paymentType"
                    value="advance"
                    checked={bookingData.paymentType === 'advance'}
                    onChange={(e) => {
                      const days = bookingData.checkinDate && bookingData.checkoutDate ? 
                        Math.ceil(Math.abs(new Date(bookingData.checkoutDate).getTime() - new Date(bookingData.checkinDate).getTime()) / (1000 * 60 * 60 * 24)) : 1;
                      const minAdvance = calculateMinAdvance(bookingData.totalAmount, days);
                      setBookingData({ ...bookingData, paymentType: 'advance', paymentAmount: minAdvance });
                    }}
                    style={{ marginRight: '10px' }}
                  />
                  <div>
                    <div style={{ fontWeight: '600', color: '#333' }}>
                      Advance Payment - ₹{(() => {
                        const days = bookingData.checkinDate && bookingData.checkoutDate ? 
                          Math.ceil(Math.abs(new Date(bookingData.checkoutDate).getTime() - new Date(bookingData.checkinDate).getTime()) / (1000 * 60 * 60 * 24)) : 1;
                        return calculateMinAdvance(bookingData.totalAmount, days);
                      })()}
                    </div>
                    <div style={{ fontSize: '0.9rem', color: '#666' }}>
                      {(() => {
                        const days = bookingData.checkinDate && bookingData.checkoutDate ? 
                          Math.ceil(Math.abs(new Date(bookingData.checkoutDate).getTime() - new Date(bookingData.checkinDate).getTime()) / (1000 * 60 * 60 * 24)) : 1;
